3	const http = require('node:http');
4	const crypto = require('node:crypto');
5	
6	function sha256Of(buffer) {
7	  return crypto.createHash('sha256').update(buffer).digest('hex');
8	}
9	
10	// A minimal in-memory stand-in for the Syncbox server's /blobs surface,
11	// used to test the client's push/pull/sync logic in isolation without
12	// depending on the server package (the client's Docker build context
13	// doesn't include it, so client tests must be self-contained).
14	//
15	// initialBlobs values may be a plain Buffer (modified_at defaults to "now")
16	// or a { buffer, modifiedAt } object -- sync's conflict rule needs tests to
17	// pin down an exact modified_at, which a bare Buffer can't express.
18	function createFakeServer(initialBlobs = {}) {
19	  const blobs = new Map(); // key -> { buffer, sha256, modifiedAt }
20	  for (const [key, value] of Object.entries(initialBlobs)) {
21	    const buffer = Buffer.isBuffer(value) ? value : value.buffer;
22	    const modifiedAt = Buffer.isBuffer(value) ? new Date().toISOString() : value.modifiedAt;
23	    blobs.set(key, { buffer, sha256: sha256Of(buffer), modifiedAt });
24	  }
25	  const puts = [];
26	
27	  const server = http.createServer((req, res) => {
28	    const chunks = [];
29	    req.on('data', (chunk) => chunks.push(chunk));
30	    req.on('end', () => {
31	      const body = Buffer.concat(chunks);
32	      const url = req.url;
33	
34	      if (req.method === 'GET' && url === '/blobs') {
35	        const items = Array.from(blobs.entries()).map(([key, blob]) => ({
