        `${result.unchanged.length} unchanged, ${result.failed.length} failed`
    );

    if (result.failed.length > 0) process.exitCode = 1;
    return;
  }
}

main().catch((err) => {
  console.error(`syncbox: unexpected error: ${err.message}`);
