    try {
      const { stdout } = await execFileAsync(process.execPath, [BIN_PATH, 'push', dir], {
        env: { ...process.env, SYNCBOX_SERVER: baseUrl },
      });
      assert.match(stdout, /uploaded a\.txt/);
    } finally {
      await fake.close();
    }
  });
});

